import{_ as r,o as n,c as s,a3 as a,j as t,a as o,t as i}from"./chunks/framework.vDgOMd_y.js";const f=JSON.parse('{"title":"Built-in Tools","description":"","frontmatter":{},"headers":[],"relativePath":"en/reference/tools.md","filePath":"en/reference/tools.md"}'),c={name:"en/reference/tools.md"};function l(d,e,u,h,m,p){return n(),s("div",null,[e[9]||(e[9]=a('<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /kimiteam/docs/en/reference/tools.md for this page in Markdown format</div><h1 id="built-in-tools" tabindex="-1">Built-in Tools <a class="header-anchor" href="#built-in-tools" aria-label="Permalink to &quot;Built-in Tools&quot;">​</a></h1><p>Built-in tools are the tool set provided by Kimi Code CLI alongside its core engine — no MCP server installation required. The Agent automatically selects and calls these tools based on the task at hand during each conversation; users can inspect the details of each tool call through the approval interface.</p><p>Compared to MCP tools, built-in tools are managed directly by the runtime, their lifecycle is bound to the session, and no external process is required. Both follow the same unified approval mechanism: <strong>read-only tools</strong> (such as <code>Read</code>, <code>Grep</code>, <code>Glob</code>) are automatically allowed by default, while <strong>write and execution tools</strong> (such as <code>Write</code>, <code>Edit</code>, <code>Bash</code>) require user approval by default. In YOLO mode, approval for regular tool calls is skipped; Plan mode exit approval is not affected.</p><h2 id="file-tools" tabindex="-1">File Tools <a class="header-anchor" href="#file-tools" aria-label="Permalink to &quot;File Tools&quot;">​</a></h2><p>File tools handle reading, writing, and searching the local filesystem — the foundation for code analysis and modification tasks.</p><table tabindex="0"><thead><tr><th>Tool</th><th>Default Approval</th><th>Description</th></tr></thead><tbody><tr><td><code>Read</code></td><td>Auto-allow</td><td>Read a text file&#39;s contents</td></tr><tr><td><code>Write</code></td><td>Requires approval</td><td>Create or overwrite a file</td></tr><tr><td><code>Edit</code></td><td>Requires approval</td><td>Precise string replacement</td></tr><tr><td><code>Grep</code></td><td>Auto-allow</td><td>Full-text search powered by ripgrep</td></tr><tr><td><code>Glob</code></td><td>Auto-allow</td><td>Find files by glob pattern</td></tr><tr><td><code>ReadMediaFile</code></td><td>Auto-allow</td><td>Read an image or video file</td></tr></tbody></table><p><strong><code>Read</code></strong> accepts a file path (<code>path</code>) plus optional <code>line_offset</code> (starting line number; negative values count from the end) and <code>n_lines</code> (maximum number of lines to read). Returns at most 1000 lines or 100 KB per call; content beyond that limit is accompanied by a truncation notice. If the file is an image or video, the tool suggests using <code>ReadMediaFile</code> instead.</p><p><strong><code>Write</code></strong> accepts <code>path</code>, <code>content</code>, and an optional <code>mode</code> (<code>overwrite</code> or <code>append</code>; defaults to overwrite). Missing parent directories are created automatically; <code>append</code> mode appends content to the end of the file without automatically adding a newline.</p><p><strong><code>Edit</code></strong> accepts <code>path</code>, <code>old_string</code> (the exact text to replace), and <code>new_string</code> (the replacement text). By default it replaces only one unique match; if the same content appears multiple times in the file, the tool returns an error and suggests using <code>replace_all: true</code>. <code>old_string</code> and <code>new_string</code> must not be identical.</p><p><strong><code>Grep</code></strong> invokes ripgrep to search file contents, supporting regular expressions (<code>pattern</code>), a search path (<code>path</code>), file type filtering (<code>type</code>, e.g., <code>ts</code>, <code>py</code>), glob filtering (<code>glob</code>), and output mode (<code>output_mode</code>: <code>files_with_matches</code> / <code>content</code> / <code>count_matches</code>; defaults to <code>files_with_matches</code>). <code>content</code> mode supports context lines (<code>-A</code>, <code>-B</code>, <code>-C</code>), case-insensitive matching (<code>-i</code>), line numbers (<code>-n</code>, default true), and multiline matching (<code>multiline</code>). All modes support <code>offset</code> + <code>head_limit</code> pagination; <code>head_limit</code> defaults to 250 and <code>0</code> means unlimited. Sensitive files such as <code>.env</code> files and private keys are automatically filtered out; set <code>include_ignored=true</code> to search files ignored by <code>.gitignore</code>, though sensitive files remain filtered.</p><p><strong><code>Glob</code></strong> matches files in a specified directory (<code>path</code>; defaults to the working directory) by glob pattern (<code>pattern</code>). Results are sorted by modification time in descending order, with a maximum of 100 entries. It respects <code>.gitignore</code>, <code>.ignore</code>, and <code>.rgignore</code> by default; set <code>include_ignored=true</code> to include ignored files such as build outputs, while sensitive files remain filtered. Brace patterns such as <code>*.{ts,tsx}</code> are supported, and broad wildcard patterns are allowed but usually truncate at the match cap.</p><p><strong><code>ReadMediaFile</code></strong> sends an image or video to the model as multimodal content. It accepts <code>path</code>, plus optional image-detail controls such as <code>region</code> and <code>full_resolution</code>; the file size limit is 100 MB. Default image reads are compressed to the configured model limits. If automatic compression cannot meet those limits safely, the tool returns an error without sending the original image and directs the model to create and read a smaller copy. Availability depends on the current model&#39;s vision capabilities (<code>image_in</code> / <code>video_in</code>).</p><h2 id="shell" tabindex="-1">Shell <a class="header-anchor" href="#shell" aria-label="Permalink to &quot;Shell&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Default Approval</th><th>Description</th></tr></thead><tbody><tr><td><code>Bash</code></td><td>Requires approval</td><td>Execute a shell command</td></tr></tbody></table><p><strong><code>Bash</code></strong> is the most permission-demanding tool and also the most general-purpose. Parameters:</p><ul><li><code>command</code> (required): the shell command to execute</li><li><code>cwd</code>: working directory</li><li><code>timeout</code>: timeout in milliseconds; foreground default is 60 seconds, maximum is 5 minutes</li><li><code>run_in_background</code>: whether to run as a background task; background tasks default to a 10-minute timeout (no timeout by default in print mode <code>kimi -p</code>)</li><li><code>description</code>: background task description; required when <code>run_in_background=true</code></li><li><code>disable_timeout</code>: whether to remove the timeout limit for background tasks</li></ul><p>Foreground mode blocks the current turn until the command completes or times out, and the TUI streams stdout and stderr into the running <code>Bash</code> tool card while the command is still active. By default, a foreground command that hits its timeout is not killed — it keeps running as a background task (bounded by the 600s default background timeout); to restore kill-on-timeout, set <a href="./../configuration/config-files.html#background"><code>bash_auto_background_on_timeout</code></a> to <code>false</code> under <code>[background]</code>. The 600s background default is configurable via <a href="./../configuration/config-files.html#background"><code>bash_task_timeout_s</code></a> (<code>0</code> = no timeout) and defaults to no timeout in print mode (<code>kimi -p</code>). Background mode returns a task ID immediately and automatically notifies the Agent when the task finishes. stdin is always closed — interactive commands receive EOF immediately. A two-phase termination strategy (SIGTERM → 5-second grace period → SIGKILL) ensures reliable process cleanup when a task is stopped or hits its background timeout. On Windows, Git Bash is used by default.</p><h2 id="web-tools" tabindex="-1">Web Tools <a class="header-anchor" href="#web-tools" aria-label="Permalink to &quot;Web Tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Default Approval</th><th>Description</th></tr></thead><tbody><tr><td><code>WebSearch</code></td><td>Auto-allow</td><td>Web search</td></tr><tr><td><code>FetchURL</code></td><td>Auto-allow</td><td>Fetch the content of a specified URL</td></tr></tbody></table><p><strong><code>WebSearch</code></strong> accepts <code>query</code> (search terms). Requires the host to provide a search implementation; when not injected, the tool does not appear in the tool list.</p><p><strong><code>FetchURL</code></strong> accepts a single <code>url</code> parameter and returns the page content. For HTML pages, the host extracts the body text rather than returning the full HTML; plain text or Markdown pages are passed through directly. Also requires a host-provided implementation.</p><h2 id="plan-mode" tabindex="-1">Plan Mode <a class="header-anchor" href="#plan-mode" aria-label="Permalink to &quot;Plan Mode&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Default Approval</th><th>Description</th></tr></thead><tbody><tr><td><code>EnterPlanMode</code></td><td>Auto-allow</td><td>Enter Plan mode</td></tr><tr><td><code>ExitPlanMode</code></td><td>Auto-allow (requires user to confirm the plan)</td><td>Exit Plan mode and submit the plan</td></tr></tbody></table><p>Plan mode is a constrained working state: once entered, <code>Write</code> and <code>Edit</code> are restricted to writing the current plan file only, and <code>TaskStop</code> is blocked entirely. All other tools (including <code>Bash</code>) are still governed by the current permission rules.</p><p><strong><code>EnterPlanMode</code></strong> accepts no parameters; upon success it returns workflow guidance and the plan file path.</p><p><strong><code>ExitPlanMode</code></strong> reads the current plan file, presents the plan to the user for approval, then exits Plan mode. The optional <code>options</code> parameter lets the Agent offer 1–3 alternative approaches (each with a <code>label</code> and <code>description</code>; <code>label</code> max 80 characters) for the user to choose from during approval. Labels must be unique and cannot use reserved words such as <code>Approve</code>, <code>Reject</code>, <code>Reject and Exit</code>, or <code>Revise</code>.</p><h2 id="state-management" tabindex="-1">State Management <a class="header-anchor" href="#state-management" aria-label="Permalink to &quot;State Management&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Default Approval</th><th>Description</th></tr></thead><tbody><tr><td><code>TodoList</code></td><td>Auto-allow</td><td>Manage a task to-do list</td></tr></tbody></table><p><strong><code>TodoList</code></strong> maintains a visible subtask list across multi-step operations; state is stored within the Agent session. The <code>todos</code> parameter accepts an array where each item has a <code>title</code> and <code>status</code> (<code>pending</code> / <code>in_progress</code> / <code>done</code>). Omitting <code>todos</code> queries the current list; passing an empty array clears it.</p><h2 id="collaboration-tools" tabindex="-1">Collaboration Tools <a class="header-anchor" href="#collaboration-tools" aria-label="Permalink to &quot;Collaboration Tools&quot;">​</a></h2><p>Collaboration tools handle inter-Agent coordination, user interaction, and Skill invocation.</p><table tabindex="0"><thead><tr><th>Tool</th><th>Default Approval</th><th>Description</th></tr></thead><tbody><tr><td><code>Agent</code></td><td>Auto-allow</td><td>Spawn a sub-Agent to execute a subtask</td></tr><tr><td><code>AgentSwarm</code></td><td>Auto-allow in swarm mode; otherwise requires approval</td><td>Launch item-based subagents or resume existing subagents</td></tr><tr><td><code>AskUserQuestion</code></td><td>Auto-allow</td><td>Ask the user a question to gather structured input</td></tr><tr><td><code>Skill</code></td><td>Auto-allow</td><td>Invoke a registered inline Skill</td></tr></tbody></table><p><strong><code>Agent</code></strong> delegates a subtask to a sub-Agent. Required parameters: <code>prompt</code> (complete task description) and <code>description</code> (a 3–5 word short summary). Optional parameters: <code>subagent_type</code> (defaults to <code>coder</code>), <code>resume</code> (ID of an existing Agent to resume; mutually exclusive with <code>subagent_type</code>), <code>run_in_background</code> (defaults to false), and <code>model</code> (any model id from <code>[models.*]</code>, <code>&quot;secondary&quot;</code> for the secondary model, or <code>&quot;primary&quot;</code> for the main model; ignored when resuming). An explicit <code>model</code> overrides the selected <a href="./../customization/agents.html#agent-file-format">agent profile&#39;s <code>model_preference</code></a> and any <code>[subagent.model_overrides]</code> config; without either, the configured secondary model is the default, or the subagent inherits the caller&#39;s model when no secondary model is configured. Agent tasks time out after 2 hours by default; the limit is configurable via <code>[subagent] timeout_ms</code> in <code>config.toml</code> (<code>0</code> = no timeout, or the <code>KIMI_SUBAGENT_TIMEOUT_MS</code> env var), and defaults to no timeout in print mode (<code>kimi -p</code>). In foreground mode the parent Agent waits for the sub-Agent to complete before continuing; in background mode a task ID is returned immediately and the result is automatically delivered back to the main Agent via a synthetic User message when done. When several foreground <code>Agent</code> calls run in the same step, the TUI groups them and shows each subagent&#39;s running, waiting, completed, or failed status with elapsed time. See <a href="./../customization/agents.html">Agent &amp; Sub-Agents</a> for details.</p>',34)),t("p",null,[e[0]||(e[0]=t("strong",null,[t("code",null,"AgentSwarm")],-1)),e[1]||(e[1]=o(" launches subagents from a shared ",-1)),e[2]||(e[2]=t("code",null,"prompt_template",-1)),e[3]||(e[3]=o(" and an ",-1)),e[4]||(e[4]=t("code",null,"items",-1)),e[5]||(e[5]=o(" array, resumes existing subagents through ",-1)),e[6]||(e[6]=t("code",null,"resume_agent_ids",-1)),e[7]||(e[7]=o(", or combines both in one call. The template must contain the ",-1)),t("code",null,i(d.item),1),e[8]||(e[8]=a(' placeholder; each item replaces that placeholder and launches one new subagent. Pass <code>subagent_type</code> to choose the profile used by every spawned subagent in the swarm, or omit it to use <code>coder</code>. Pass <code>model</code> (any model id from <code>[models.*]</code>, <code>&quot;secondary&quot;</code>, or <code>&quot;primary&quot;</code>) to run item-spawned subagents on a specified model; <code>item_models</code> overrides per-item — a table keyed by item index mapping each item to its model id, with <strong>priority above <code>model</code></strong>. This explicit choice overrides the selected <a href="./../customization/agents.html#agent-file-format">agent profile&#39;s <code>model_preference</code></a> and any <code>[subagent.model_overrides]</code> config; without either, the configured secondary model is the default, or the subagent inherits the caller&#39;s model when no secondary model is configured. Resumed subagents keep their own model. Without <code>resume_agent_ids</code>, the tool requires at least 2 items; with <code>resume_agent_ids</code>, it can resume one or more existing subagents. The tool supports up to 128 total subagents, waits for all subagents to finish, and returns an aggregated report. In the TUI, foreground swarms show a live <code>Agent swarm</code> progress panel above the input box. If a model response calls <code>AgentSwarm</code>, that call must be the only tool call in the response; to run multiple swarms, call one <code>AgentSwarm</code>, wait for its result, then call the next, or combine the work into one swarm when a single template can cover it. In <code>manual</code> permission mode, <code>AgentSwarm</code> calls outside active swarm mode request approval unless a permission rule allows them; while swarm mode is active, <code>AgentSwarm</code> itself is auto-approved. Permission rules match <code>AgentSwarm</code> by tool name only — argument patterns such as <code>AgentSwarm(swarm)</code> are not supported. By default the tool ramps up concurrency without an upper limit (5 subagents start immediately, then 1 more every 700 ms); set <code>KIMI_CODE_AGENT_SWARM_MAX_CONCURRENCY</code> to a positive integer to cap how many subagents run at the same time during that ramp, or leave it unset for no cap. If it is set to a value that is not a positive integer, the AgentSwarm call fails fast.',43))]),e[10]||(e[10]=a('<p><strong><code>AskUserQuestion</code></strong> asks the user a structured multiple-choice question — useful for disambiguation or option selection. The <code>questions</code> parameter accepts 1–4 questions; each question requires <code>question</code> (ending with <code>?</code>), <code>options</code> (2–4 choices, each with a <code>label</code> and <code>description</code>), and optional <code>header</code> (max 12 characters) and <code>multi_select</code> (defaults to false). An &quot;Other&quot; option is appended automatically. Setting <code>background</code> to true starts a background question task and returns a task ID immediately. When the host does not support interactive questioning, a failure message is returned and the Agent should ask the user directly in a text reply instead.</p><p><strong><code>Skill</code></strong> allows the Agent to actively invoke a registered inline-type Skill. Accepts <code>skill</code> (the Skill name) and optional <code>args</code> (additional argument text). Only <code>type = &quot;inline&quot;</code> Skills can be called via this tool; Skills with <code>disableModelInvocation: true</code> are rejected. Maximum nesting depth is 3 levels. See <a href="./../customization/skills.html">Agent Skills</a> for details.</p><h2 id="team-management-main-agent-only" tabindex="-1">Team Management (Main Agent Only) <a class="header-anchor" href="#team-management-main-agent-only" aria-label="Permalink to &quot;Team Management (Main Agent Only)&quot;">​</a></h2><p>These four tools are available to the main Agent alone; subagents calling them will be rejected.</p><table tabindex="0"><thead><tr><th>Tool</th><th>Default Approval</th><th>Description</th></tr></thead><tbody><tr><td><code>TeamHire</code></td><td>Requires approval</td><td>Hire a new team member: creates an agent profile in user or project directory under <code>.kimi-code/agents</code>; errors if same-name exists</td></tr><tr><td><code>TeamFire</code></td><td>Requires approval</td><td>Fire a member: deletes the corresponding agent file; performance data is retained</td></tr><tr><td><code>TeamScore</code></td><td>Requires approval</td><td>Score work: 0–100 with notes, attributed to the running model id</td></tr><tr><td><code>TeamMessage</code></td><td>Requires approval</td><td>Deliver a message: soft reminder (insert into current turn) or interrupt-and-correct (cancel current turn first)</td></tr></tbody></table><p><strong><code>TeamHire</code></strong> accepts parameters <code>name</code> (kebab-case file name), <code>role</code> (optional job title), <code>description</code>, <code>whenToUse</code> (optional), <code>prompt</code> (system prompt body), <code>model</code> (optional — any model id from <code>[models.*]</code> or <code>&quot;primary&quot;</code> / <code>&quot;secondary&quot;</code>; omitted means the profile&#39;s <code>model_preference</code> controls subsequent behavior), <code>tools</code> / <code>disallowedTools</code> (optional, same syntax as agent file), <code>subagents</code> (optional), <code>duty</code> (optional boolean), and <code>scope</code> (optional <code>&quot;user&quot;</code> or <code>&quot;project&quot;</code>, default <code>&quot;user&quot;</code>). Writes to <code>~/.kimi-code/agents/&lt;name&gt;.md</code> or <code>&lt;cwd&gt;/.kimi-code/agents/&lt;name&gt;.md</code>. If same-name already exists, errors instead of silently overwriting; prompt users to fire then hire. After writing, the directory watcher auto-reloads and the member is immediately dispatchable. When autonomously forming a team, the main Agent should directly decide name / role / description / prompt / model without asking item by item — available model ids are listed in <code>[models]</code> config section.</p><p><strong><code>TeamFire</code></strong> accepts <code>name</code> and optional <code>scope</code> (defaults to same as Hire). Locates and deletes the corresponding agent file; errors if not found, listing all currently existing profiles. Performance records in <code>performance.json</code> are retained. The watcher auto-reloads afterwards, making that member undispachable.</p><p><strong><code>TeamScore</code></strong> accepts <code>profile</code> (agent name to score), <code>score</code> (integer 0–100), <code>note</code> (review comments), and optional <code>model</code> (omitted — tool auto-resolves the profile&#39;s current effective binding). Writes to persistent storage and echoes the profile&#39;s updated summary (with byModel grouping results). The core purpose of scoring is to evaluate <strong>whether a &quot;member × model&quot; pairing is competent</strong> — when a profile consistently scores low on a particular model, the main Agent should switch via <code>[subagent.model_overrides]</code> or recommend another available id from <code>[models]</code>.</p><p><strong><code>TeamMessage</code></strong> accepts <code>agent_id</code> (task ID returned by Agent/AgentSwarm dispatch results and TaskOutput metadata), <code>message</code> (text to deliver), and optional <code>interrupt</code> (default false):</p><ul><li><strong>Soft reminder</strong> (<code>interrupt: false</code>, default): injects the message as a synthetic user message into the running subagent&#39;s current turn; if idle, starts a new turn.</li><li><strong>Interrupt-and-correct</strong> (<code>interrupt: true</code>): cancels the subagent&#39;s current turn output first, then injects the new instruction — semantically equivalent to pressing ESC twice in the terminal to interrupt and re-enter.</li></ul><p>Fire-and-forget single delivery; responses flow back through existing task result/ notification channels. If the target agent does not exist, lists available agents; for terminated members, suggests <code>Agent resume</code> instead.</p><h2 id="background-tasks" tabindex="-1">Background Tasks <a class="header-anchor" href="#background-tasks" aria-label="Permalink to &quot;Background Tasks&quot;">​</a></h2><p>Background task tools manage tasks started via <code>Bash</code>, <code>Agent</code>, or <code>AskUserQuestion</code>. When a task reaches a terminal state, its status and saved output path are automatically delivered back to the Agent; use <code>TaskOutput</code> to check progress early.</p><table tabindex="0"><thead><tr><th>Tool</th><th>Default Approval</th><th>Description</th></tr></thead><tbody><tr><td><code>TaskList</code></td><td>Auto-allow</td><td>List background tasks</td></tr><tr><td><code>TaskOutput</code></td><td>Auto-allow</td><td>View the output of a background task</td></tr><tr><td><code>TaskStop</code></td><td>Requires approval</td><td>Stop a running background task</td></tr></tbody></table><p><strong><code>TaskList</code></strong> returns the list of background tasks. Optional parameters: <code>active_only</code> (defaults to true; lists only running tasks) and <code>limit</code> (defaults to 20; range 1–100).</p><p><strong><code>TaskOutput</code></strong> returns the status and output of a task given its <code>task_id</code>. The inline preview includes at most the most recent 32 KB of content; the full log is saved to disk, and the tool also returns an <code>output_path</code> with a suggestion to use <code>Read</code> for paginated access. The call is always non-blocking — it returns the current snapshot immediately, and task completion is delivered via automatic notification.</p><p><strong><code>TaskStop</code></strong> accepts a <code>task_id</code> and optional <code>reason</code> (defaults to <code>Stopped by TaskStop</code>). Safe to call on tasks that are already in a terminal state.</p><h2 id="scheduled-tasks" tabindex="-1">Scheduled Tasks <a class="header-anchor" href="#scheduled-tasks" aria-label="Permalink to &quot;Scheduled Tasks&quot;">​</a></h2><p>Scheduled task tools allow the Agent to re-inject a prompt into the current session at a future time — either as a one-time reminder or as a recurring cron-triggered task (periodic checks, daily reports, deployment monitoring, etc.). Schedules are bound to the session and remain active when you resume it with <code>kimi --session</code>, but are not carried into a brand-new session. A single session can hold at most 50 active scheduled tasks. Set <code>KIMI_DISABLE_CRON=1</code> to disable them entirely; see <a href="./../configuration/env-vars.html#runtime-switches">Environment Variables</a>.</p><table tabindex="0"><thead><tr><th>Tool</th><th>Default Approval</th><th>Description</th></tr></thead><tbody><tr><td><code>CronCreate</code></td><td>Requires approval</td><td>Schedule a prompt to fire at a future time</td></tr><tr><td><code>CronList</code></td><td>Auto-allow</td><td>List scheduled tasks</td></tr><tr><td><code>CronDelete</code></td><td>Requires approval</td><td>Cancel a scheduled task</td></tr></tbody></table><p><strong><code>CronCreate</code></strong> accepts <code>cron</code> (a standard 5-field cron expression in the user&#39;s local timezone: <code>minute hour day-of-month month day-of-week</code>), <code>prompt</code> (the text to inject when triggered; UTF-8 limit 8 KB), and optional <code>recurring</code> (defaults to <code>true</code>; pass <code>false</code> for a one-time reminder that auto-deletes after firing). On success, returns an 8-hex-digit <code>id</code>, a human-readable <code>humanSchedule</code> (e.g., <code>every 5 minutes</code>), and <code>nextFireAt</code> (the ISO timestamp of the next fire time).</p><p>To prevent all users from firing at the same time on the hour, the scheduler applies deterministic jitter: recurring tasks are shifted forward by <code>min(10% of the period, 15 minutes)</code>; one-time tasks that fall exactly on <code>:00</code> or <code>:30</code> are moved forward by up to 90 seconds. If the scheduler misses several fire times (e.g., because the laptop was sleeping), it fires only once on wake-up — the prompt is wrapped in a <code>&lt;cron-fire&gt;</code> envelope with a <code>coalescedCount</code>. Recurring tasks that have been alive for more than 7 days fire one final time with <code>stale=&quot;true&quot;</code> and are then automatically deleted; call <code>CronCreate</code> again to keep them.</p><p><strong><code>CronList</code></strong> is a read-only tool that accepts no parameters. It returns one record per active task with fields: <code>id</code>, <code>cron</code>, <code>humanSchedule</code>, <code>nextFireAt</code>, <code>recurring</code>, <code>ageDays</code>, and <code>stale</code>. Records are separated by <code>---</code> and sorted by schedule time.</p><p><strong><code>CronDelete</code></strong> accepts a single <code>id</code>. For recurring tasks, all future fires stop immediately; for one-time tasks, the pending fire is cancelled. One-time tasks that have already fired are auto-deleted, so calling <code>CronDelete</code> on an already-fired one-time task returns <code>No cron job with id ...</code>. Deletion is irreversible — use <code>CronCreate</code> again to restore. <code>CronDelete</code> is also blocked in Plan mode.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./../customization/agents.html">Agent &amp; Sub-Agents</a> — Scheduling mechanics and context isolation for the <code>Agent</code> tool</li><li><a href="./../customization/hooks.html">Hooks</a> — Trigger local scripts before and after tool calls</li><li><a href="./slash-commands.html">Slash Commands</a> — Quick reference for TUI built-in control commands</li></ul>',26))])}const b=r(c,[["render",l]]);export{f as __pageData,b as default};
